template <typename T>
T clampValue(T value, T low, T high)
{
    if (value < low) return low;
    if (value > high) return high;
    return value;
}

unitTests:
TEST("ints") { CHECK_EQ(clampValue(15, 0, 10), 10); CHECK_EQ(clampValue(-4, 0, 10), 0); CHECK_EQ(clampValue(6, 0, 10), 6); }
TEST("doubles") { CHECK_NEAR(clampValue(1.5, 0.0, 1.0), 1.0, 1e-12); CHECK_NEAR(clampValue(0.25, 0.0, 1.0), 0.25, 1e-12); }
TEST("the ends are allowed") { CHECK_EQ(clampValue(0, 0, 10), 0); CHECK_EQ(clampValue(10, 0, 10), 10); }

